INSERT INTO public.words (word, meaning, category, rarity, classe, origem, curiosidade, pronuncia, exemplo, nivel, sinonimos) VALUES
('algazarra', 'gritaria alegre, vozerio', 'regional', 2, 'substantivo', 'do árabe al-gazara, "abundância"', 'Veio do árabe com os mouros e virou o barulho oficial de recreio de escola.', 'al-ga-ZAR-ra', 'A algazarra das crianças tomou o quintal.', 'facil', ARRAY['gritaria','vozerio']),
('fugaz', 'que passa rapidamente, efêmero', 'qualidade', 2, 'adjetivo', 'do latim fugax, "que foge"', 'Parente direto de "fuga": o que é fugaz está literalmente fugindo do tempo.', 'fu-GAZ', 'A fama nas redes costuma ser fugaz.', 'facil', ARRAY['efêmero','passageiro','breve']),
('rebuliço', 'agitação, alvoroço', 'regional', 2, 'substantivo', 'incerta', 'O rebuliço é o alvoroço com fofoca dentro: quando começa, todo mundo quer saber o motivo.', 're-bu-LI-ço', 'A visita surpresa causou rebuliço no escritório.', 'facil', ARRAY['alvoroço','agitação']),
('estripulia', 'travessura, peraltice', 'infantil', 2, 'substantivo', 'incerta', 'Palavra oficial das avós para as artes das crianças — sempre no plural: "que estripulias são essas?"', 'es-tri-pu-LI-a', 'O gato aprontou mais uma estripulia na cozinha.', 'facil', ARRAY['travessura','arte','peraltice']),
('lengalenga', 'ladainha comprida e monótona', 'regional', 2, 'substantivo', 'formação expressiva', 'A repetição da própria palavra já imita o que ela significa: len-ga-len-ga, sem fim.', 'len-ga-LEN-ga', 'Começou a mesma lengalenga de sempre sobre o trânsito.', 'facil', ARRAY['ladainha','cantilena']),
('supetão', 'ato repentino; "de supetão" = de repente', 'regional', 2, 'substantivo', 'incerta', 'Só existe na expressão "de supetão" — ninguém nunca viu um supetão sozinho.', 'su-pe-TÃO', 'Chegou de supetão, sem avisar ninguém.', 'facil', ARRAY['repente']),
('zanga', 'irritação, aborrecimento', 'sentimento', 2, 'substantivo', 'incerta', 'Em Portugal e na África lusófona é mais comum que "raiva" — e rende o verbo zangar-se.', 'ZAN-ga', 'A zanga passou assim que ele pediu desculpas.', 'facil', ARRAY['irritação','bronca']),
('gatuno', 'ladrão, larápio', 'pessoa', 2, 'substantivo', 'de gato (que anda de mansinho)', 'O ladrão que anda como gato: silencioso, ágil e de mansinho — daí o nome.', 'ga-TU-no', 'O gatuno levou só o celular e as chaves.', 'facil', ARRAY['ladrão','larápio','meliante']),
('destempero', 'descontrole, exagero destemperado', 'sentimento', 2, 'substantivo', 'de des- + temperar', 'Vem da cozinha: comida sem tempero certo, pessoa sem controle certo.', 'des-tem-PE-ro', 'Respondeu num destempero de que se arrependeu.', 'facil', ARRAY['descontrole','exagero']),
('embromação', 'enrolação, adiamento proposital', 'regional', 2, 'substantivo', 'de embromar', 'Patrimônio nacional da procrastinação: a arte de prometer para amanhã o que não se fará nunca.', 'em-bro-ma-ÇÃO', 'Aquele orçamento era pura embromação.', 'facil', ARRAY['enrolação','embuste']),
('lero-lero', 'conversa fiada, papo furado', 'regional', 2, 'substantivo', 'formação expressiva', 'O lero-lero é a conversa que gira em círculos — muito papo, zero conteúdo.', 'LE-ro-LE-ro', 'Deixou de lero-lero e foi direto ao ponto.', 'facil', ARRAY['papo furado','conversa fiada']),
('tabefe', 'tapa, bofetada', 'regional', 2, 'substantivo', 'incerta', 'O tapa de comédia antiga: ninguém leva um tabefe sem plateia rindo.', 'ta-BE-fe', 'Levou um tabefe da avó por mexer na panela.', 'facil', ARRAY['tapa','bofetada','sopapo']),
('acepipe', 'petisco fino, iguaria', 'gastronomia', 2, 'substantivo', 'incerta', 'Palavra de cardápio empolado: todo tira-gosto vira "acepipe" quando o restaurante quer cobrar mais caro.', 'a-ce-PI-pe', 'A mesa veio cheia de acepipes e ninguém jantou.', 'medio', ARRAY['petisco','iguaria','quitute']),
('afã', 'empenho ansioso, faina', 'sentimento', 2, 'substantivo', 'incerta', 'Cabe numa sílaba e meia todo o esforço do mundo: "no afã de terminar, errou tudo".', 'a-FÃ', 'No afã de agradar, exagerou no presente.', 'medio', ARRAY['ânsia','empenho','faina']),
('algaravia', 'fala confusa, misturada e incompreensível', 'regional', 2, 'substantivo', 'do árabe al-arabiya, "a língua árabe"', 'Para os portugueses medievais, o árabe soava confuso — e "a língua árabe" virou sinônimo de falatório ininteligível.', 'al-ga-ra-VI-a', 'A reunião virou uma algaravia de siglas.', 'medio', ARRAY['falatório','confusão']),
('arcabouço', 'estrutura, esqueleto de algo', 'objeto', 2, 'substantivo', 'incerta', 'Serve para prédio, lei e argumento: tudo que sustenta por dentro é arcabouço.', 'ar-ca-BOU-ço', 'O arcabouço da casa ficou pronto em um mês.', 'medio', ARRAY['estrutura','esqueleto','armação']),
('bulício', 'agitação viva e ruidosa', 'regional', 2, 'substantivo', 'do latim bullire, "ferver"', 'A cidade que "ferve" tem bulício: o mesmo latim de "ebulição" borbulha aqui.', 'bu-LÍ-cio', 'O bulício do mercado começava antes do sol.', 'medio', ARRAY['agitação','burburinho']),
('caramanchão', 'estrutura de jardim coberta por trepadeiras', 'lugar', 2, 'substantivo', 'incerta', 'Cenário obrigatório de pedido de casamento em novela de época.', 'ca-ra-man-CHÃO', 'Tomavam chá no caramanchão aos domingos.', 'medio', ARRAY['pérgula']),
('celeuma', 'discussão barulhenta, polêmica', 'nautica', 2, 'substantivo', 'do grego kéleusma, "canto dos remadores"', 'Era o grito ritmado que coordenava os remadores das galés — o barulho do mar virou o barulho da polêmica.', 'ce-LEU-ma', 'A mudança de regra causou celeuma no campeonato.', 'medio', ARRAY['polêmica','controvérsia']),
('escrutínio', 'exame minucioso; apuração de votos', 'direito', 2, 'substantivo', 'do latim scrutari, "vasculhar"', 'No latim, scruta eram trastes: escrutinar era revirar até o lixo atrás de algo — hoje é revirar votos e reputações.', 'es-cru-TÍ-nio', 'A proposta passou pelo escrutínio da assembleia.', 'medio', ARRAY['exame','apuração']),
('esdrúxulo', 'esquisito, extravagante', 'qualidade', 2, 'adjetivo', 'do italiano sdrucciolo', 'Na gramática, é a palavra proparoxítona; fora dela, tudo que soa torto e estranho.', 'es-DRÚ-xu-lo', 'Apareceu com uma teoria esdrúxula sobre o jogo.', 'medio', ARRAY['estapafúrdio','excêntrico']),
('estrambótico', 'extravagante, esquisitão', 'qualidade', 2, 'adjetivo', 'do italiano strambotto', 'Vem de um tipo de poema italiano cheio de exageros — o exagero ficou, a poesia se perdeu.', 'es-tram-BÓ-ti-co', 'Usava óculos estrambóticos de aro dourado.', 'medio', ARRAY['excêntrico','esquisito']),
('farfalhar', 'produzir ruído leve de folhas ou tecido', 'verbo', 2, 'verbo', 'formação expressiva', 'O som exato de vento em árvore e de saia de festa: a palavra imita o próprio barulho.', 'far-fa-LHAR', 'As cortinas farfalhavam com a brisa.', 'medio', ARRAY['sussurrar','roçar']),
('finório', 'esperto dissimulado, astuto', 'pessoa', 2, 'adjetivo', 'de fino', 'O esperto "fino demais": elogio pela metade, desconfiança inteira.', 'fi-NÓ-rio', 'Aquele vendedor finório empurrou o modelo antigo.', 'medio', ARRAY['matreiro','astuto','ladino']),
('galhofa', 'zombaria alegre, brincadeira ruidosa', 'sentimento', 2, 'substantivo', 'incerta', 'A zombaria sem maldade: quem faz galhofa ri COM você — na teoria.', 'ga-LHO-fa', 'Levou o tombo na galhofa e riu junto.', 'medio', ARRAY['troça','zombaria','chacota']),
('hecatombe', 'desastre com muitas vítimas, catástrofe', 'literatura', 2, 'substantivo', 'do grego hekatón + boûs, "cem bois"', 'Na Grécia antiga era literalmente o sacrifício de cem bois aos deuses — sobrou só a mortandade no sentido moderno.', 'e-ca-TOM-be', 'O vazamento foi uma hecatombe para os peixes do rio.', 'medio', ARRAY['catástrofe','tragédia']),
('inaudito', 'nunca ouvido; extraordinário, sem precedente', 'qualidade', 2, 'adjetivo', 'do latim inauditus', 'Literalmente "jamais ouvido": todo escândalo de manchete é inaudito até o próximo.', 'i-nau-DI-to', 'Foi uma decisão inaudita na história do clube.', 'medio', ARRAY['inédito','extraordinário']),
('matraca', 'instrumento de estalos; pessoa que fala sem parar', 'objeto', 2, 'substantivo', 'do árabe mitraqa, "martelo"', 'O instrumento de madeira que estala na Semana Santa emprestou o nome para a língua que não para.', 'ma-TRA-ca', 'A matraca da vizinha atravessou o almoço inteiro.', 'medio', ARRAY['tagarela','taramela']),
('mazela', 'doença leve; problema crônico', 'medicina', 2, 'substantivo', 'do latim macella', 'Serve para o joelho e para o país: toda crônica de política fala nas "mazelas" de algo.', 'ma-ZE-la', 'Voltou do inverno com as mazelas de sempre.', 'medio', ARRAY['achaque','moléstia']),
('quezília', 'desavença, implicância', 'sentimento', 2, 'substantivo', 'do quimbundo', 'Trazida de Angola, é a briga pequena que dura: implicância com CPF e endereço.', 'que-ZÍ-lia', 'Havia uma velha quezília entre os dois primos.', 'medio', ARRAY['rixa','implicância','desavença']),
('resfolegar', 'respirar com esforço, ofegar', 'verbo', 2, 'verbo', 'do latim refollicare', 'O verbo oficial de quem sobe escada carregando compras: parou, resfolegou, continuou.', 'res-fo-le-GAR', 'Chegou ao topo resfolegando como um fole.', 'medio', ARRAY['ofegar','arfar']),
('saracotear', 'rebolar, mover-se com requebros', 'verbo', 2, 'verbo', 'incerta', 'O andar que dança sem música — toda festa de família tem alguém saracoteando primeiro.', 'sa-ra-co-te-AR', 'Saracoteava pela sala ao som do rádio.', 'medio', ARRAY['rebolar','requebrar','gingar']),
('soslaio', 'de través, obliquamente (olhar de soslaio)', 'comportamento', 2, 'substantivo', 'incerta', 'O olhar de canto de olho que finge não olhar — usado quase só na expressão "de soslaio".', 'sos-LAI-o', 'Mediu o rival de soslaio antes de falar.', 'medio', ARRAY['viés','esguelha']),
('venta', 'narina (geralmente no plural: ventas)', 'corpo', 2, 'substantivo', 'do latim ventus, "vento"', 'É por onde entra o vento — e para onde vai o dedo do adversário nas expressões: "na venta!"', 'VEN-ta', 'O boi resfolegou soltando ar pelas ventas.', 'medio', ARRAY['narina','fuça']),
('mofino', 'infeliz, mesquinho, sem sorte', 'literatura', 2, 'adjetivo', 'incerta', 'Palavra de auto de Gil Vicente: o azarado nato do teatro clássico português.', 'mo-FI-no', 'Sentia-se o mais mofino dos mortais naquela manhã.', 'medio', ARRAY['desventurado','mesquinho']),
('peralta', 'criança travessa; janota do séc. XVIII', 'infantil', 2, 'substantivo', 'incerta', 'Antes de virar criança arteira, "peralta" era o dândi exagerado de Lisboa no século XVIII — o influencer de calção e peruca.', 'pe-RAL-ta', 'O peralta escondeu o controle remoto de novo.', 'medio', ARRAY['travesso','arteiro','traquinas']),
('parlenda', 'versinho infantil de tradição oral', 'infantil', 2, 'substantivo', 'do latim parlare, "falar"', '"Um, dois, feijão com arroz" é parlenda — poesia de boca em boca que nenhum livro inventou.', 'par-LEN-da', 'A turma recitava parlendas na roda.', 'dificil', ARRAY['quadrinha','rima infantil']),
('diáfano', 'translúcido, delicado, quase transparente', 'qualidade', 3, 'adjetivo', 'do grego diaphanés', 'Queridinha dos poetas para véus, névoas e pretextos: tudo que deixa a luz (ou a intenção) passar.', 'di-Á-fa-no', 'Uma cortina diáfana filtrava o sol da tarde.', 'dificil', ARRAY['translúcido','etéreo','ténue']),
('dislate', 'disparate, absurdo', 'literatura', 3, 'substantivo', 'do espanhol dislate', 'O disparate de gala: quando o absurdo é dito em discurso solene, é dislate.', 'dis-LA-te', 'O relatório continha um dislate por página.', 'dificil', ARRAY['disparate','absurdo','despautério']),
('contumaz', 'teimoso, que reincide obstinadamente', 'direito', 3, 'adjetivo', 'do latim contumax', 'Termo de tribunal: o "réu contumaz" é o que não aparece nunca — teimosia com consequências jurídicas.', 'con-tu-MAZ', 'Era um faltoso contumaz nas reuniões.', 'dificil', ARRAY['reincidente','obstinado','renitente']),
('incúria', 'negligência, desleixo', 'direito', 3, 'substantivo', 'do latim incuria', 'O contrário exato de "cuidado": a incúria é a assinatura invisível em todo desastre evitável.', 'in-CÚ-ria', 'O prédio ruiu por décadas de incúria.', 'dificil', ARRAY['negligência','desleixo','desídia']),
('jactância', 'vanglória, gabolice arrogante', 'comportamento', 3, 'substantivo', 'do latim jactantia, "ato de lançar"', 'Do mesmo latim de "jato": quem se jacta fica se lançando para cima — geralmente sem combustível.', 'jac-TÂN-cia', 'Falava das próprias vitórias com jactância.', 'dificil', ARRAY['vanglória','bazófia','gabolice']),
('idílio', 'romance ingênuo; cena bucólica e serena', 'literatura', 3, 'substantivo', 'do grego eidýllion, "quadrinho"', 'Nasceu como "pequeno quadro" de poesia pastoral — hoje é o namoro de verão que a gente jura que foi perfeito.', 'i-DÍ-lio', 'Viveram um idílio de férias na serra.', 'dificil', ARRAY['romance','devaneio']),
('néscio', 'ignorante, tolo', 'pessoa', 3, 'adjetivo', 'do latim nescius, "que não sabe"', 'Etimologia impiedosa: ne + scire = "não saber". O néscio é, literalmente, o sem-saber.', 'NÉS-cio', 'Só um néscio ignoraria os avisos.', 'dificil', ARRAY['ignorante','tolo','estulto']),
('vitupério', 'insulto grave, afronta pública', 'literatura', 3, 'substantivo', 'do latim vituperium', 'O xingamento de tragédia clássica: ninguém sofre vitupério no grupo da família, só em ato solene.', 'vi-tu-PÉ-rio', 'Saiu da sessão sob vitupérios da plateia.', 'dificil', ARRAY['afronta','injúria','doesto']),
('verve', 'inspiração vivaz no falar ou escrever', 'literatura', 3, 'substantivo', 'do francês verve', 'A faísca do improviso: cronista sem verve é relógio sem corda.', 'VER-ve', 'Respondeu com a verve de sempre e arrancou risos.', 'dificil', ARRAY['eloquência','brilho']),
('cicerone', 'guia que acompanha visitantes', 'pessoa', 3, 'substantivo', 'de Cícero, orador romano', 'Os guias de Roma falavam tanto quanto Cícero — e o nome do orador virou profissão.', 'ci-ce-RO-ne', 'Fez de cicerone dos primos pela cidade velha.', 'dificil', ARRAY['guia','acompanhante']),
('circunlóquio', 'rodeio de palavras para dizer algo simples', 'literatura', 3, 'substantivo', 'do latim circum + loqui, "falar em volta"', 'A arte de dar três voltas na frase para não dizer "não" — especialidade de comunicado oficial.', 'cir-cun-LÓ-quio', 'Pediu aumento num circunlóquio de dez minutos.', 'dificil', ARRAY['rodeio','perífrase']),
('cornucópia', 'símbolo da abundância em forma de chifre', 'literatura', 3, 'substantivo', 'do latim cornu copiae, "chifre da abundância"', 'O chifre transbordando frutas das pinturas antigas — de onde a mitologia tirava o buffet infinito.', 'cor-nu-CÓ-pia', 'A feira era uma cornucópia de cores e cheiros.', 'dificil', ARRAY['fartura','abundância']),
('apanágio', 'atributo característico, marca própria', 'literatura', 3, 'substantivo', 'do francês apanage', 'Era a renda dada aos príncipes sem trono; hoje é o que "pertence por natureza": a elegância como apanágio.', 'a-pa-NÁ-gio', 'A ironia fina era seu apanágio.', 'dificil', ARRAY['atributo','distintivo']),
('arrivista', 'quem quer subir na vida a qualquer custo', 'pessoa', 3, 'substantivo', 'do francês arriviste', 'O que importa é "chegar" (arriver) — de preferência pisando no menor número de testemunhas.', 'ar-ri-VIS-ta', 'O arrivista trocava de opinião conforme a plateia.', 'dificil', ARRAY['oportunista','trepador']),
('alvíssaras', 'recompensa a quem traz boa notícia', 'regional', 3, 'substantivo', 'do árabe al-bishara, "boa nova"', 'Os cartazes antigos de "perdido-se gratifica" pediam alvíssaras — a gorjeta oficial da boa notícia.', 'al-VÍS-sa-ras', 'Deu alvíssaras ao menino que achou a carteira.', 'insano', ARRAY['recompensa','gratificação']),
('cáfila', 'caravana de camelos; bando de gente má', 'nautica', 3, 'substantivo', 'do árabe qafila', 'Dos desertos para os insultos: a caravana virou "corja" na boca dos indignados do século XIX.', 'CÁ-fi-la', 'Uma cáfila de aproveitadores rondava o leilão.', 'insano', ARRAY['corja','súcia','bando']),
('sestro', 'mania, cacoete; má sorte', 'comportamento', 3, 'substantivo', 'do latim sinistrum, "esquerdo"', 'Do mesmo latim de "sinistro": o lado esquerdo era o do agouro, e o cacoete herdou o nome.', 'SES-tro', 'Tinha o sestro de ajeitar os óculos ao mentir.', 'insano', ARRAY['cacoete','mania','tique']),
('facúndia', 'eloquência abundante, facilidade de falar', 'literatura', 4, 'substantivo', 'do latim facundia', 'O dom de falar bonito sem parar — vendedores natos têm facúndia de fábrica.', 'fa-CÚN-dia', 'Convenceu o júri com pura facúndia.', 'insano', ARRAY['eloquência','loquacidade']),
('garrulice', 'tagarelice ruidosa', 'comportamento', 4, 'substantivo', 'do latim garrulus, "tagarela"', 'Os romanos chamavam os pássaros barulhentos de garruli — a gaiola mudou, o barulho não.', 'gar-ru-LI-ce', 'A garrulice da mesa ao lado impedia o café em paz.', 'insano', ARRAY['tagarelice','loquacidade']),
('encômio', 'elogio solene, louvor formal', 'literatura', 4, 'substantivo', 'do grego enkómion', 'Era o poema oficial para vencedores de jogos gregos — o troféu falado.', 'en-CÔ-mio', 'Recebeu encômios da banca inteira.', 'insano', ARRAY['louvor','panegírico','elogio']),
('inópia', 'pobreza extrema, escassez total', 'direito', 4, 'substantivo', 'do latim inopia', 'Aparece em petições jurídicas para atestar que o réu está sem um tostão: "em estado de inópia".', 'i-NÓ-pia', 'A família vivia em completa inópia.', 'insano', ARRAY['penúria','miséria','indigência']),
('locupletar', 'enriquecer, encher-se (à custa alheia)', 'direito', 4, 'verbo', 'do latim locupletare', 'Verbo favorito dos tribunais: ninguém "se locupleta" honestamente — a palavra já nasce culpada.', 'lo-cu-ple-TAR', 'Foi acusado de se locupletar com verbas públicas.', 'insano', ARRAY['enriquecer','abarrotar']),
('perfunctório', 'superficial, feito por mera obrigação', 'qualidade', 4, 'adjetivo', 'do latim perfunctorius', 'O cumprimento de metas sem alma: leitura perfunctória é a que os olhos fazem sem avisar o cérebro.', 'per-func-TÓ-rio', 'Deu uma olhada perfunctória no contrato e assinou.', 'insano', ARRAY['superficial','displicente']),
('prosápia', 'vaidade de linhagem, arrogância de berço', 'pessoa', 4, 'substantivo', 'do latim prosapia, "estirpe"', 'A soberba de quem cita o sobrenome antes do argumento — "gente de prosápia" raramente paga a conta.', 'pro-SÁ-pia', 'Falava dos antepassados com prosápia insuportável.', 'insano', ARRAY['soberba','empáfia','arrogância']),
('tirocínio', 'experiência prática, discernimento adquirido', 'direito', 4, 'substantivo', 'do latim tirocinium, "primeiro serviço do recruta"', 'O "tiro" era o soldado novato em Roma; tirocínio era seu batismo de fogo. Sobrou o aprendizado, sumiu a guerra.', 'ti-ro-CÍ-nio', 'Resolveu o impasse com o tirocínio de trinta anos de balcão.', 'insano', ARRAY['experiência','discernimento']),
('homizio', 'refúgio de fugitivo, esconderijo', 'direito', 4, 'substantivo', 'do latim homicidium (evolução p/ "abrigar-se")', 'Termo do direito antigo: dar homizio a alguém era crime de esconder criminoso — a palavra em si já foragiu do uso.', 'o-MÍ-zio', 'A fazenda serviu de homizio ao coronel foragido.', 'insano', ARRAY['esconderijo','refúgio','couto']),
('baldaquino', 'dossel ornamental sobre trono ou altar', 'objeto', 4, 'substantivo', 'do italiano baldacchino, "tecido de Bagdá"', 'O tecido de luxo vinha de Baldacco — o nome italiano de Bagdá. A cidade virou móvel de igreja.', 'bal-da-QUI-no', 'O altar abrigava-se sob um baldaquino dourado.', 'insano', ARRAY['dossel','sobrecéu'])
